import re
def live_cache(entries,now):
 if type(now) is not int or not 0<=now<=10000000:return None
 d={};out=[];key=re.compile(r'[a-z][a-z0-9]*(?:-[a-z0-9]+)*')
 for x in entries:
  if len(x)!=4 or not key.fullmatch(x[0]) or x[0] in d:return None
  try:w,t=int(x[2]),int(x[3])
  except:return None
  if str(w)!=x[2] or str(t)!=x[3] or not 0<=w<=10000000 or not 0<=t<=10000000 or (t and w+t>10000000):return None
  d[x[0]]=1
  if t==0 or now<w+t:out.append(x[0]+'='+x[1])
 return sorted(out)
